<script setup lang="ts">import{ref,onMounted,onUnmounted}from'vue';import{api}from'../api';import PageHeader from'../components/PageHeader.vue';import DataTable from'../components/DataTable.vue';const rows=ref<any[]>([]);const cols=[{key:'created_at',label:'Data/hora'},{key:'action',label:'Ação'},{key:'resource_type',label:'Recurso'},{key:'resource_id',label:'Identificador'},{key:'details',label:'Detalhes'}];async function load(){rows.value=(await api.get('/audit-events')).data}onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))</script><template><PageHeader title="Auditoria" subtitle="Trilha imutável das operações administrativas e fiscais"/><section class="panel"><DataTable :columns="cols" :rows="rows"><template #cell-created_at="{value}">{{new Date(value).toLocaleString('pt-BR')}}</template><template #cell-details="{value}"><code class="json-mini">{{JSON.stringify(value)}}</code></template></DataTable></section></template>
